// Interpretable 12-hour PM2.5 forecast: ridge regression on lagged PM2.5, weather and hour-of-day.
// Evaluated on a chronological hold-out (never shuffled) against two baselines.
var runAt = new Date().toISOString();
var H = 12;
function logOut(status, records, message) {
  return { json: { kind: 'log', run_at: runAt, run_id: 'fc' + Date.now(), source: 'forecast', status: status, records: records, message: String(message).substring(0, 400) } };
}
var aq, wx;
try { aq = $('Fetch AQ History').first().json; wx = $('Fetch Weather History').first().json; } catch (e) { return [logOut('failed', 0, 'Upstream fetch did not run')]; }
if (!aq || !aq.hourly || !aq.hourly.time || !wx || !wx.hourly || !wx.hourly.time) {
  return [logOut('failed', 0, 'History data unavailable (air quality or weather request failed); no forecast issued')];
}
var times = aq.hourly.time;
var pm = aq.hourly.pm2_5;
var wmap = {};
for (var i = 0; i < wx.hourly.time.length; i++) wmap[wx.hourly.time[i]] = i;
var nowMs = Date.now();
var nowIdx = -1;
for (var k = 0; k < times.length; k++) { if (Date.parse(times[k] + ':00Z') <= nowMs) nowIdx = k; }
