  var p0 = val(pm, t), p3 = val(pm, t - 3), p6 = val(pm, t - 6), p12 = val(pm, t - 12), p24 = val(pm, t - 24);
  var ws = val(wx.hourly.wind_speed_10m, wi), tc = val(wx.hourly.temperature_2m, wi), rh = val(wx.hourly.relative_humidity_2m, wi);
  if (p0 === null || p3 === null || p6 === null || p12 === null || p24 === null || ws === null || tc === null || rh === null) return null;
  var hr = new Date(Date.parse(times[t] + ':00Z')).getUTCHours();
  return { x: [p0, p3, p6, p12, p24, ws, tc, rh, Math.sin(2 * Math.PI * hr / 24), Math.cos(2 * Math.PI * hr / 24)], hr: hr };
}
var rowsX = [];
for (var t = 24; t <= nowIdx - H; t++) {
  var f = feat(t);
  var y = val(pm, t + H);
  if (f && y !== null) rowsX.push({ x: f.x, y: y, hr: f.hr });
}
if (rowsX.length < 200) { return [logOut('failed', rowsX.length, 'Not enough complete history rows to train (' + rowsX.length + ')')]; }
var trainN = Math.floor(rowsX.length * 0.75);
var train = rowsX.slice(0, trainN);
var test = rowsX.slice(trainN + H);
if (test.length < 24) { return [logOut('failed', rowsX.length, 'Hold-out set too small')]; }
var d = train[0].x.length;
var mean = [], sd = [];
for (var j = 0; j < d; j++) {
  var s = 0;
  for (var a = 0; a < train.length; a++) s += train[a].x[j];
  var m = s / train.length;
  var v = 0;
  for (var b = 0; b < train.length; b++) v += Math.pow(train[b].x[j] - m, 2);
  mean.push(m); sd.push(Math.sqrt(v / train.length) || 1);
}
var ybar = 0;
for (var c = 0; c < train.length; c++) ybar += train[c].y;
ybar = ybar / train.length;
function z(x) { var o = []; for (var q = 0; q < d; q++) o.push((x[q] - mean[q]) / sd[q]); return o; }
var A = [], bvec = [];
for (var r = 0; r < d; r++) { var rowA = []; for (var cc = 0; cc < d; cc++) rowA.push(r === cc ? 1.0 : 0); A.push(rowA); bvec.push(0); }
for (var n = 0; n < train.length; n++) {
  var zz = z(train[n].x);
  for (var r2 = 0; r2 < d; r2++) {
    bvec[r2] += zz[r2] * (train[n].y - ybar);
    for (var c2 = 0; c2 < d; c2++) A[r2][c2] += zz[r2] * zz[c2];
  }
}
function solve(M, vec) {
  var N = vec.length;
  for (var i1 = 0; i1 < N; i1++) M[i1].push(vec[i1]);
  for (var col = 0; col < N; col++) {
    var piv = col;
    for (var r3 = col + 1; r3 < N; r3++) { if (Math.abs(M[r3][col]) > Math.abs(M[piv][col])) piv = r3; }
    var tmp = M[col]; M[col] = M[piv]; M[piv] = tmp;
    var dv = M[col][col];
    if (Math.abs(dv) < 1e-12) return null;
    for (var j1 = col; j1 <= N; j1++) M[col][j1] = M[col][j1] / dv;
    for (var r4 = 0; r4 < N; r4++) {
      if (r4 !== col) {
        var fct = M[r4][col];
        if (fct !== 0) { for (var j2 = col; j2 <= N; j2++) M[r4][j2] -= fct * M[col][j2]; }
