  hourN[th] = (hourN[th] || 0) + 1;
  allSum += train[e].y;
}
function seasonal(hr) { var th2 = (hr + H) % 24; return hourN[th2] ? hourSum[th2] / hourN[th2] : allSum / train.length; }
var eM = [0, 0], eP = [0, 0], eS = [0, 0];
for (var g = 0; g < test.length; g++) {
  var tr = test[g];
  var dm = predict(tr.x) - tr.y, dp = tr.x[0] - tr.y, ds = seasonal(tr.hr) - tr.y;
  eM[0] += Math.abs(dm); eM[1] += dm * dm;
  eP[0] += Math.abs(dp); eP[1] += dp * dp;
  eS[0] += Math.abs(ds); eS[1] += ds * ds;
}
var nT = test.length;
function r2d(v) { return Math.round(v * 100) / 100; }
var maeM = r2d(eM[0] / nT), maeP = r2d(eP[0] / nT), maeS = r2d(eS[0] / nT);
var rmseM = r2d(Math.sqrt(eM[1] / nT)), rmseP = r2d(Math.sqrt(eP[1] / nT)), rmseS = r2d(Math.sqrt(eS[1] / nT));
var beats = maeM < maeP && maeM < maeS && rmseM < rmseP && rmseM < rmseS;
var fNow = feat(nowIdx);
if (!fNow) { return [logOut('failed', rowsX.length, 'Latest observation incomplete; no forecast issued rather than showing an old one')]; }
var tgtIdx = nowIdx + H;
var cams = tgtIdx < pm.length ? val(pm, tgtIdx) : null;
var issued = new Date(Date.parse(times[nowIdx] + ':00Z')).toISOString();
var target = new Date(Date.parse(times[nowIdx] + ':00Z') + H * 3600000).toISOString();
var fcRow = {
  kind: 'forecast', issued_at: issued, target_time: target, location: 'Lahore centre (31.52N, 74.35E)',
  pm25_now: r2d(fNow.x[0]), pm25_model: r2d(predict(fNow.x)), pm25_persistence: r2d(fNow.x[0]), pm25_seasonal: r2d(seasonal(fNow.hr)), pm25_cams: cams === null ? null : r2d(cams),
  mae_model: maeM, mae_persistence: maeP, mae_seasonal: maeS, rmse_model: rmseM, rmse_persistence: rmseP, rmse_seasonal: rmseS,
  beats_baselines: beats, train_rows: train.length, test_rows: nT
};
var msg = 'MAE model ' + maeM + ' vs persistence ' + maeP + ' vs seasonal ' + maeS + '; RMSE ' + rmseM + ' / ' + rmseP + ' / ' + rmseS + '. ' + (beats ? 'Model beats both baselines on the hold-out.' : 'Model does NOT beat both baselines on the hold-out; treat the forecast with caution.');
return [{ json: fcRow }, logOut('ok', 1, msg)];
